"""
verify_qr.py — utility script to decode and visualize the Digital Health Twin QR
Usage:
    1. Copy the 'qr_png_base64' value from /generate-dht-qr output.
    2. Paste it into the `QR_BASE64_STRING` variable below.
    3. Run: python utils/verify_qr.py
    4. It will save 'decoded_qr.png' and display it.
"""

import base64
from io import BytesIO
from PIL import Image
import matplotlib.pyplot as plt

# ---- Paste your QR base64 value here ----
QR_BASE64_STRING = """

""".strip()

if not QR_BASE64_STRING:
    print("⚠️ Please paste your qr_png_base64 value in QR_BASE64_STRING above.")
    exit()

# Decode and save
img_bytes = base64.b64decode(QR_BASE64_STRING)
img = Image.open(BytesIO(img_bytes))
img.save("decoded_qr.png")

# Display it
plt.imshow(img)
plt.axis("off")
plt.title("Decoded Digital Health Twin QR")
plt.show()

print("✅ QR image saved as decoded_qr.png and displayed successfully.")
